(2245665, 308077, 46468, '<td valign="top">Like the idea and the contrast between the green and amber glass. I would have preferred to see into the green bottle more, like you can with the amber one. Also, in my opinion, the glare at the top above the amber bottle is very distracting. Really like the play of light on the amber bottle though. Good luck</td>', 'Like the idea and the contrast between the green and amber glass. I would have preferred to see into the green bottle more, like you can with the amber one. Also, in my opinion, the glare at the top above the amber bottle is very distracting. Really like the play of light on the amber bottle though. Good luck', '2006-03-21 22:50:30.000000', NULL, 1),
(2245675, 307000, 46468, '<td valign="top">Really love the way you have framed the cityscape. Fantastic how you have kept the focus on both the near rocks and still maintain focus on the city. In my opinion, the blue of the sky and the presence of the cloud at the top really adds to the photo. Well done</td>', 'Really love the way you have framed the cityscape. Fantastic how you have kept the focus on both the near rocks and still maintain focus on the city. In my opinion, the blue of the sky and the presence of the cloud at the top really adds to the photo. Well done', '2006-03-21 22:53:16.000000', NULL, 1),
(2245680, 308316, 46468, '<td valign="top">The torches really add an unusual effect. Well done. Love how everyone is moving around the two people in the middle, really makes them stand out.</td>', 'The torches really add an unusual effect. Well done. Love how everyone is moving around the two people in the middle, really makes them stand out.', '2006-03-21 22:55:09.000000', NULL, 1),
(2245687, 307939, 46468, '<td valign="top">Beautifully done. Good focus on the white building, it really stands out and well placed on the thirds, nice framing with the leaves on both sides of the photo. Well done</td>', 'Beautifully done. Good focus on the white building, it really stands out and well placed on the thirds, nice framing with the leaves on both sides of the photo. Well done', '2006-03-21 22:57:46.000000', NULL, 1),
(2245694, 307793, 46468, '<td valign="top">Really like how the black background emphasizes the shell and its reflection. Nicely done</td>', 'Really like how the black background emphasizes the shell and its reflection. Nicely done', '2006-03-21 22:59:37.000000', NULL, 1),
(2245701, 308680, 46468, '<td valign="top">Beautiful blue sky against the cliff, well done exposure on the rushing water without much blown highlights and absolutely love the rainbow. Good luck</td>', 'Beautiful blue sky against the cliff, well done exposure on the rushing water without much blown highlights and absolutely love the rainbow. Good luck', '2006-03-21 23:03:23.000000', NULL, 1),
(2245715, 307726, 7194, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2006-03-21 23:09:32.000000', NULL, 1),
(2245725, 308877, 46468, '<td valign="top">Beautiful blue water, good composition and lighting. Well done</td>', 'Beautiful blue water, good composition and lighting. Well done', '2006-03-21 23:12:02.000000', NULL, 1),
(2245835, 308375, 35334, '<td valign="top">Another nice waterfall.</td>', 'Another nice waterfall.', '2006-03-21 23:46:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2245853, 308522, 35334, '<td valign="top">I like this but I find it hard to believe that it is a two second exposure.</td>', 'I like this but I find it hard to believe that it is a two second exposure.', '2006-03-21 23:49:26.000000', NULL, 1),
(2245863, 308134, 35334, '<td valign="top">Another nice night shot. I''d like to see a little less black at the top and a little more at the bottom and right of the photo.</td>', 'Another nice night shot. I''d like to see a little less black at the top and a little more at the bottom and right of the photo.', '2006-03-21 23:50:57.000000', NULL, 1),
(2245866, 308222, 35334, '<td valign="top">One of the best of the waterfall shots!</td>', 'One of the best of the waterfall shots!', '2006-03-21 23:51:32.000000', NULL, 1),
(2245873, 308570, 35334, '<td valign="top">It is a nice shot but it certainly doesn''t look like late night.</td>', 'It is a nice shot but it certainly doesn''t look like late night.', '2006-03-21 23:53:06.000000', NULL, 1),
(2245877, 307991, 13688, '<td valign="top">i really like your image.  it seems almost like an optical illusion to me as it seems we are looking up at the rim but down at the base.  i also really like how it has a earlier 20th century feel and the overall lighting with it flowing in at the rim and then washing around at the bottom of the glass.  I''m trying hard to get on board with your choice of composition, but I think I''d enjoy this even more without the reflection.  Still pretty darn nice.</td>', 'i really like your image.  it seems almost like an optical illusion to me as it seems we are looking up at the rim but down at the base.  i also really like how it has a earlier 20th century feel and the overall lighting with it flowing in at the rim and then washing around at the bottom of the glass.  I''m trying hard to get on board with your choice of composition, but I think I''d enjoy this even more without the reflection.  Still pretty darn nice.', '2006-03-21 23:53:53.000000', NULL, 1),
(2245878, 308475, 35334, '<td valign="top">Yet another second hand--better than many.</td>', 'Yet another second hand--better than many.', '2006-03-21 23:54:11.000000', NULL, 1),
(2245881, 308738, 35334, '<td valign="top">Nice. I would like to see the entrances.</td>', 'Nice. I would like to see the entrances.', '2006-03-21 23:55:08.000000', NULL, 1),
(2245888, 308404, 35334, '<td valign="top">I really like the feel of this. The sky color, sea color, and rock color are all right on.</td>', 'I really like the feel of this. The sky color, sea color, and rock color are all right on.', '2006-03-21 23:56:33.000000', NULL, 1),
(2245896, 307334, 13688, '<td valign="top">nice flow.  very reflaxing.  wish your colors and composition had a bit more pop.  i''m wondering what it would have looked like if you concentrated more on the rocks and avoided getting the far bank in the frame.</td>', 'nice flow.  very reflaxing.  wish your colors and composition had a bit more pop.  i''m wondering what it would have looked like if you concentrated more on the rocks and avoided getting the far bank in the frame.', '2006-03-21 23:58:27.000000', NULL, 1),
