(2258356, 307079, 36060, '<td valign="top">Great shot.</td>', 'Great shot.', '2006-03-25 17:29:54.000000', NULL, 1),
(2258359, 307256, 40370, '<td valign="top">I like this better than the similar watch images, your tight crop and clarity gives you an extra points with me.</td>', 'I like this better than the similar watch images, your tight crop and clarity gives you an extra points with me.', '2006-03-25 17:30:25.000000', NULL, 1),
(2258360, 308188, 40370, '<td valign="top">I love the light trails, more unusual than regular old red brake lights.</td>', 'I love the light trails, more unusual than regular old red brake lights.', '2006-03-25 17:31:28.000000', NULL, 1),
(2258362, 308189, 36060, '<td valign="top">Great shot.</td>', 'Great shot.', '2006-03-25 17:31:51.000000', NULL, 1),
