(2258422, 307007, 40370, '<td valign="top">Gorgeous !!</td>', 'Gorgeous !!', '2006-03-25 18:00:40.000000', NULL, 1),
(2258425, 307009, 40370, '<td valign="top">Nice, like the different tree tops, reminds me of Christmas tree shopping, I can just picture the "star" on top. Nice moon too.</td>', 'Nice, like the different tree tops, reminds me of Christmas tree shopping, I can just picture the "star" on top. Nice moon too.', '2006-03-25 18:02:02.000000', NULL, 1),
(2258699, 307196, 45764, '<td valign="top">This is something like another picture, but the background is amazing!  The moon on the lake, Stunning!</td>', 'This is something like another picture, but the background is amazing!  The moon on the lake, Stunning!', '2006-03-25 20:27:09.000000', NULL, 1),
(2258737, 307039, 34069, '<td valign="top">I like this pattern but the graininess takes away from it, for me anyway.</td>', 'I like this pattern but the graininess takes away from it, for me anyway.', '2006-03-25 20:47:02.000000', NULL, 1),
(2258741, 308647, 34069, '<td valign="top">The color and contrast in this one seem a bit flat to me.  I would have boosted saturation and/or contrast a bit.</td>', 'The color and contrast in this one seem a bit flat to me.  I would have boosted saturation and/or contrast a bit.', '2006-03-25 20:48:02.000000', NULL, 1),
(2258744, 308084, 34069, '<td valign="top">I like this pattern but overall it is more subdued, almost hazy, than I like.  I would have bumped the contrast up a bit.</td>', 'I like this pattern but overall it is more subdued, almost hazy, than I like.  I would have bumped the contrast up a bit.', '2006-03-25 20:49:26.000000', NULL, 1),
(2258751, 308027, 34069, '<td valign="top">Excellent.  I like how you''ve frozen the fingers in what look like only two positions, rather than just a smooth blur.  Selective desaturation works well here, too.  I might have removed the capo for simplicity''s sake (no one can hear the music in the photo).  But, this is one of my favorite images this challenge.</td>', 'Excellent.  I like how you''ve frozen the fingers in what look like only two positions, rather than just a smooth blur.  Selective desaturation works well here, too.  I might have removed the capo for simplicity''s sake (no one can hear the music in the photo).  But, this is one of my favorite images this challenge.', '2006-03-25 20:53:36.000000', NULL, 1),
(2258754, 308680, 34069, '<td valign="top">There were many waterfall shots in this challenge but this one is my favorite.  I like that you managed to catch the rainbow in the mist.  The rich colors in the rock wall make it stand out, as does the deep blue sky.</td>', 'There were many waterfall shots in this challenge but this one is my favorite.  I like that you managed to catch the rainbow in the mist.  The rich colors in the rock wall make it stand out, as does the deep blue sky.', '2006-03-25 20:55:18.000000', NULL, 1),
(2258756, 307871, 34069, '<td valign="top">Beautifully illustrates two seconds'' worth of motion.  The lighting works well here, too, fading off into darkness in the distance.</td>', 'Beautifully illustrates two seconds'' worth of motion.  The lighting works well here, too, fading off into darkness in the distance.', '2006-03-25 20:56:10.000000', NULL, 1),
(2258762, 308215, 34069, '<td valign="top">Great idea.  I probably would have monkeyed with curves or contrast to make the background go black entirely.</td>', 'Great idea.  I probably would have monkeyed with curves or contrast to make the background go black entirely.', '2006-03-25 21:01:05.000000', NULL, 1),
(2258763, 308869, 34069, '<td valign="top">The fire looks a bit posterized, but I like the concept.</td>', 'The fire looks a bit posterized, but I like the concept.', '2006-03-25 21:02:13.000000', NULL, 1),
(2258764, 307151, 34069, '<td valign="top">I like this scene.  I do wish the front of the garage weren''t standing out so brightly, though.</td>', 'I like this scene.  I do wish the front of the garage weren''t standing out so brightly, though.', '2006-03-25 21:03:20.000000', NULL, 1),
(2258767, 308357, 34069, '<td valign="top">Very like a painting.  If anything, almost too intense for my taste.</td>', 'Very like a painting.  If anything, almost too intense for my taste.', '2006-03-25 21:04:15.000000', NULL, 1),
(2258768, 306829, 12962, '<td valign="top">Nice blurring of the moon.  It''s usually difficult to take a photograph of the full moon at 2 secs.</td>', 'Nice blurring of the moon.  It''s usually difficult to take a photograph of the full moon at 2 secs.', '2006-03-25 21:05:14.000000', NULL, 1),
(2258770, 307441, 12962, '<td valign="top">Wow, she must have sat so still ... nice highlights, beautiful model!</td>', 'Wow, she must have sat so still ... nice highlights, beautiful model!', '2006-03-25 21:05:47.000000', NULL, 1),
(2258771, 308375, 12962, '<td valign="top">Beautiful silky water ...</td>', 'Beautiful silky water ...', '2006-03-25 21:06:05.000000', NULL, 1),
(2258773, 307256, 12962, '<td valign="top">Good black and white treatment ... DOF is great here too!</td>', 'Good black and white treatment ... DOF is great here too!', '2006-03-25 21:07:14.000000', NULL, 1),
(2258775, 308254, 12962, '<td valign="top">Top notch! Hope you do well.</td>', 'Top notch! Hope you do well.', '2006-03-25 21:07:49.000000', NULL, 1),
(2258777, 308507, 12962, '<td valign="top">That is soooo good!  I predict a winner (at least in my book, it''s a winner).</td>', 'That is soooo good!  I predict a winner (at least in my book, it''s a winner).', '2006-03-25 21:09:00.000000', NULL, 1),
(2258780, 307019, 12962, '<td valign="top">Shades of dsidwell.  Very nice!</td>', 'Shades of dsidwell.  Very nice!', '2006-03-25 21:09:52.000000', NULL, 1),
(2258789, 308766, 12962, '<td valign="top">Unique and original ...</td>', 'Unique and original ...', '2006-03-25 21:18:08.000000', NULL, 1),
(2258792, 308851, 12962, '<td valign="top">Beautiful background ... like a painting almost.</td>', 'Beautiful background ... like a painting almost.', '2006-03-25 21:19:29.000000', NULL, 1),
(2258793, 307991, 12962, '<td valign="top">Love it!</td>', 'Love it!', '2006-03-25 21:20:04.000000', NULL, 1),
(2258796, 308316, 12962, '<td valign="top">This is wonderful!  It''s perfect for the challenge.  It''s great that you have one of your elements in focus and everyone around him sort of fade away.  Lots of stories to tell.</td>', 'This is wonderful!  It''s perfect for the challenge.  It''s great that you have one of your elements in focus and everyone around him sort of fade away.  Lots of stories to tell.', '2006-03-25 21:22:48.000000', NULL, 1),
(2258798, 307930, 12962, '<td valign="top">Excellent!!! Ten.</td>', 'Excellent!!! Ten.', '2006-03-25 21:23:24.000000', NULL, 1),
(2258815, 307199, 33400, '<td valign="top">Love the light and shadow to accentuate the condition of the roses.  Nicely done.</td>', 'Love the light and shadow to accentuate the condition of the roses.  Nicely done.', '2006-03-25 21:38:54.000000', NULL, 1),
(2258820, 307353, 33400, '<td valign="top">Great colors and excellent clarity.  Makes the picture jump out - nicely done.</td>', 'Great colors and excellent clarity.  Makes the picture jump out - nicely done.', '2006-03-25 21:41:29.000000', NULL, 1),
(2258823, 308338, 33400, '<td valign="top">Intriguing and fun.  I keep coming back to this one.  Bumping up.</td>', 'Intriguing and fun.  I keep coming back to this one.  Bumping up.', '2006-03-25 21:42:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2258877, 307150, 54540, '<td valign="top">If I''m not mistaken, I have this same style clock on my coffee maker!  Cool!</td>', 'If I''m not mistaken, I have this same style clock on my coffee maker!  Cool!', '2006-03-25 22:02:46.000000', NULL, 1),
(2258913, 307079, 12962, '<td valign="top">This is the best among the waterfalls I have seen so far ... good perspective, nice milky structure, great colors.</td>', 'This is the best among the waterfalls I have seen so far ... good perspective, nice milky structure, great colors.', '2006-03-25 22:16:42.000000', NULL, 1),
(2258915, 308043, 12962, '<td valign="top">Wow, what an explosion of colors!  Black background is soo appropriate for this composition.  Top notch!</td>', 'Wow, what an explosion of colors!  Black background is soo appropriate for this composition.  Top notch!', '2006-03-25 22:17:17.000000', NULL, 1),
(2258922, 307267, 12962, '<td valign="top">Should win, or at least top ten.  Beautiful and simple.  The lines going or coming from one point outside the frame on the right makes this also quite dynamic. Also the placement of the dividing line between the sky and the water is perfect, it divides the frame into unequal frame adding more to the tension between the sky and the water.  10.</td>', 'Should win, or at least top ten.  Beautiful and simple.  The lines going or coming from one point outside the frame on the right makes this also quite dynamic. Also the placement of the dividing line between the sky and the water is perfect, it divides the frame into unequal frame adding more to the tension between the sky and the water.  10.', '2006-03-25 22:19:50.000000', NULL, 1),
(2258938, 308404, 12962, '<td valign="top">Great mood you''ve depicted here ... just a suggestion when you add this to your dpcprints:  clone out or crop that piece of island on the right, once I saw it, my eyes got pulled me in preventing me from exploring your excellent shot. Beautiful division into three layers.  9.</td>', 'Great mood you''ve depicted here ... just a suggestion when you add this to your dpcprints:  clone out or crop that piece of island on the right, once I saw it, my eyes got pulled me in preventing me from exploring your excellent shot. Beautiful division into three layers.  9.', '2006-03-25 22:23:48.000000', NULL, 1),
(2258943, 308318, 12962, '<td valign="top">Very clever!</td>', 'Very clever!', '2006-03-25 22:24:56.000000', NULL, 1),
(2258945, 308680, 12962, '<td valign="top">Should be top ten.</td>', 'Should be top ten.', '2006-03-25 22:25:17.000000', NULL, 1),
(2258955, 308722, 12962, '<td valign="top">What a wonderful choice subject for this challenge.  Composition is great, beautiful silky water, background is tops to isolate the water and dolphins.  Hope you win!!! Ten from me.</td>', 'What a wonderful choice subject for this challenge.  Composition is great, beautiful silky water, background is tops to isolate the water and dolphins.  Hope you win!!! Ten from me.', '2006-03-25 22:28:04.000000', NULL, 1),
(2258958, 308650, 12962, '<td valign="top">Good concept ...</td>', 'Good concept ...', '2006-03-25 22:28:37.000000', NULL, 1),
(2258965, 308188, 12962, '<td valign="top">Colors and light and motion makes this sooo delicious to look at.  Smooth.  10.</td>', 'Colors and light and motion makes this sooo delicious to look at.  Smooth.  10.', '2006-03-25 22:29:19.000000', NULL, 1),
(2258969, 308324, 12962, '<td valign="top">The background elements are a bonus for this wonderful piece.</td>', 'The background elements are a bonus for this wonderful piece.', '2006-03-25 22:30:50.000000', NULL, 1),
(2258982, 308357, 12962, '<td valign="top">Very brave ... (I like high key photos and composition like this but I am not quite sure how this would be received here.)  But your passion is quite admirable.  The only criticism I can offer you is the midplacement between top and bottom makes this composition static - if you place it somewhere an inch up or down, the division between top and bottom would be unequal and would offer additional movement/tension.  9.</td>', 'Very brave ... (I like high key photos and composition like this but I am not quite sure how this would be received here.)  But your passion is quite admirable.  The only criticism I can offer you is the midplacement between top and bottom makes this composition static - if you place it somewhere an inch up or down, the division between top and bottom would be unequal and would offer additional movement/tension.  9.', '2006-03-25 22:34:51.000000', NULL, 1),
(2259002, 307196, 39850, '<td valign="top">8 - Good and unusual.  Nice complementary &amp; interesting background.  Colors are nice and look natural, not selectively desaturated.  The only thing in my opinion is the clothing - doesn''t really suit, but minor.  Good use of the 2 sec exposure.</td>', '8 - Good and unusual.  Nice complementary & interesting background.  Colors are nice and look natural, not selectively desaturated.  The only thing in my opinion is the clothing - doesn''t really suit, but minor.  Good use of the 2 sec exposure.', '2006-03-25 22:40:45.000000', NULL, 1),
(2259016, 306322, 39850, '<td valign="top">6 - A more finely tuned crop at the top would have made this even better in my opinion.</td>', '6 - A more finely tuned crop at the top would have made this even better in my opinion.', '2006-03-25 22:43:35.000000', NULL, 1),
(2259036, 307005, 42567, '<td valign="top">this is really cool!  9</td>', 'this is really cool!  9', '2006-03-25 22:49:06.000000', NULL, 1),
(2259039, 307196, 42567, '<td valign="top">WOW..this is wild!</td>', 'WOW..this is wild!', '2006-03-25 22:50:01.000000', NULL, 1),
(2259090, 307019, 39850, '<td valign="top">8 - Very nice.  Difficult to crop at the top any differently, there''s always going to be stars on the edge of the frame.  Perhaps just a little more color/tonal range/depth may have given this a little extra, not sure.</td>', '8 - Very nice.  Difficult to crop at the top any differently, there''s always going to be stars on the edge of the frame.  Perhaps just a little more color/tonal range/depth may have given this a little extra, not sure.', '2006-03-25 23:09:26.000000', NULL, 1),
(2259095, 308418, 39850, '<td valign="top">4 - Good potential.  A different crop (especially the incoming on the right), more balance/symmetry, a slight tweaking of color (especially that yellow) <i>and</i> a ''petrified look'' on the face (or a different title) would all have made this much better in my opinion.</td>', '4 - Good potential.  A different crop (especially the incoming on the right), more balance/symmetry, a slight tweaking of color (especially that yellow) and a ''petrified look'' on the face (or a different title) would all have made this much better in my opinion.', '2006-03-25 23:12:07.000000', NULL, 1),
(2259098, 308245, 39850, '<td valign="top">7 - Very nice.  Depending what is there/you had to work with <i>perhaps</i> more trees at the top and less ''fore'' may have given this a really strong edge - but I realize quite a different shot to what you have.  The balance and the contrasting textures and colors make it seem like there is/was good potential ''there''.  A more finely tuned crop on the left too.  Like the ice sheet ''canopy'' on the right.</td>', '7 - Very nice.  Depending what is there/you had to work with perhaps more trees at the top and less ''fore'' may have given this a really strong edge - but I realize quite a different shot to what you have.  The balance and the contrasting textures and colors make it seem like there is/was good potential ''there''.  A more finely tuned crop on the left too.  Like the ice sheet ''canopy'' on the right.', '2006-03-25 23:15:53.000000', NULL, 1),
(2259104, 308404, 39850, '<td valign="top">7 - Nice.  A more finely tuned crop on the right make this even better in my opinion.</td>', '7 - Nice.  A more finely tuned crop on the right make this even better in my opinion.', '2006-03-25 23:21:44.000000', NULL, 1),
(2259116, 308375, 39850, '<td valign="top">8 - Good perspective/angle.  Apologies in advance if wrong, but looks like it needs a <i>fraction</i> nudge rotation up on the right.  Good depth/focal range.</td>', '8 - Good perspective/angle.  Apologies in advance if wrong, but looks like it needs a fraction nudge rotation up on the right.  Good depth/focal range.', '2006-03-25 23:30:28.000000', NULL, 1),
(2259153, 307198, 39850, '<td valign="top">7 - Very good perspective, good coloring.  Horizon looks like it needs a fraction up on the left.  Perhaps on the whole, this more centered, or otherwise more off-set, have made this even better in my opinion.</td>', '7 - Very good perspective, good coloring.  Horizon looks like it needs a fraction up on the left.  Perhaps on the whole, this more centered, or otherwise more off-set, have made this even better in my opinion.', '2006-03-25 23:46:20.000000', NULL, 1),
(2259161, 306259, 39850, '<td valign="top">6 - Good and unusual.  If the car/houses were not so apparent and the blades on the windmill ''somehow'' a fraction more ''captured''/contrasted, make this even better in my opinion.  Haven''t seen a windmill shot like this before.</td>', '6 - Good and unusual.  If the car/houses were not so apparent and the blades on the windmill ''somehow'' a fraction more ''captured''/contrasted, make this even better in my opinion.  Haven''t seen a windmill shot like this before.', '2006-03-25 23:49:14.000000', NULL, 1),
(2259165, 308526, 22734, '<td valign="top">Super cool! Bump.</td>', 'Super cool! Bump.', '2006-03-25 23:51:14.000000', NULL, 1),
(2259199, 306313, 39850, '<td valign="top">8 - Very nice.  Like that cloud capture - more of that might have given this a little extra in my opinion.  The shadows from them(?) on the mountains more discernable too (contrasted), but likely difficult.</td>', '8 - Very nice.  Like that cloud capture - more of that might have given this a little extra in my opinion.  The shadows from them(?) on the mountains more discernable too (contrasted), but likely difficult.', '2006-03-26 00:03:26.000000', NULL, 1),
(2259439, 307198, 37893, '<td valign="top">Hello Bear ;)Great landscape as always ;) I envy the beautiful colors that you are able to capture in your corner of the world ;)</td>', 'Hello Bear ;)Great landscape as always ;) I envy the beautiful colors that you are able to capture in your corner of the world ;)', '2006-03-26 04:08:33.000000', NULL, 1),
(2259459, 308087, 55922, '<td valign="top">i love the simplicity and creativity</td>', 'i love the simplicity and creativity', '2006-03-26 04:47:24.000000', NULL, 1),
(2259471, 307198, 27735, '<td valign="top">Bear, is this yours? :-) Awesome lighting!</td>', 'Bear, is this yours? :-) Awesome lighting!', '2006-03-26 05:20:41.000000', NULL, 1),
(2259519, 308222, 55066, '<td valign="top">Cool Pic i love the depth of filed</td>', 'Cool Pic i love the depth of filed', '2006-03-26 07:31:38.000000', NULL, 1),
