(2260602, 306689, 30982, '<td valign="top">Good balance, composition, and nifty end result!</td>', 'Good balance, composition, and nifty end result!', '2006-03-26 18:48:19.000000', NULL, 1),
(2260605, 308526, 30982, '<td valign="top">Nice idea and good execution.</td>', 'Nice idea and good execution.', '2006-03-26 18:49:40.000000', NULL, 1),
