(2263314, 308858, 51538, '<td valign="top">My monitor needs a tuning - because I cannot see any smoke.  However, I did vote this high as I like the shot.<br/><br/><i>Message edited by author 2006-03-27 10:20:23.</i></td>', 'My monitor needs a tuning - because I cannot see any smoke.  However, I did vote this high as I like the shot.', '2006-03-27 11:19:58.000000', '2006-03-27 11:20:23.000000', 0),
(2263315, 308752, 35804, '<td valign="top">2 seconds for a cat shot is AMAZING! You are sooooooo right about this being a one off...I don''t think I have ever come close with all the cat pictures I have taken...a really nice image Brad, in every sort of way.</td>', '2 seconds for a cat shot is AMAZING! You are sooooooo right about this being a one off...I don''t think I have ever come close with all the cat pictures I have taken...a really nice image Brad, in every sort of way.', '2006-03-27 11:20:40.000000', NULL, 0),
(2263318, 308633, 51538, '<td valign="top">Traveling back in time as well as into the distance.  One of my favourites from this challenge.</td>', 'Traveling back in time as well as into the distance.  One of my favourites from this challenge.', '2006-03-27 11:22:00.000000', NULL, 0),
(2263320, 307522, 51538, '<td valign="top">I like the balance between movement and stillness, one hand and the other.  Very nice.<br/><br/><i>Message edited by author 2006-03-27 10:23:33.</i></td>', 'I like the balance between movement and stillness, one hand and the other.  Very nice.', '2006-03-27 11:22:59.000000', '2006-03-27 11:23:33.000000', 0),
